package android.os; import java.util.*; public class Handler { private record Job(long time,long id,Runnable run) {} private static long now,seq; private static final List<Job> jobs=new ArrayList<>(); public Handler(Looper l){} public boolean post(Runnable r){return postDelayed(r,0);} public boolean postDelayed(Runnable r,long delay){jobs.add(new Job(now+delay,seq++,r));return true;} public void removeCallbacks(Runnable r){jobs.removeIf(j->j.run()==r);} public static int pending(){return jobs.size();} public static void reset(){jobs.clear();now=0;seq=0;Looper.worker=false;} public static void advance(long ms){long end=now+ms; for(;;){Job next=jobs.stream().filter(j->j.time()<=end).min(Comparator.comparingLong(Job::time).thenComparingLong(Job::id)).orElse(null);if(next==null)break;jobs.remove(next);now=next.time();next.run().run();}now=end;} }
